-- Semilla de la carta estructurada (carta impresa de La Gambeta, 22/09). NO se aplica sola.
-- Requiere la migración 0015. Vincula cada línea al producto de Fudo por fudo_id (los precios salen de Fudo).
-- Líneas sin producto en Fudo quedan con producto_id NULL (se ven sin precio y marcadas en el admin).
-- Idempotente: borra y vuelve a crear solo las secciones con id 'carta-sec-*'.
DELETE FROM carta_items WHERE seccion_id LIKE 'carta-sec-%';
DELETE FROM carta_secciones WHERE id LIKE 'carta-sec-%';
